mapper.select:
SELECT t.COUNTER_TRADER id, t.COUNTER_TRADER text FROM ( SELECT DISTINCT etr.COUNTER_TRADER FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
AND etr.COUNTER_ID = #{counterId}
) t
t.COUNTER_TRADER like concat('%',concat(#{search},'%'))
t.COUNTER_TRADER like concat('%',concat(#{param},'%'))
and t.COUNTER_TRADER is not null

SELECT TEMP.* FROM ( SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR AS finpordName, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, floor(NVL(TEMP.AMOUNT, 0)/100) AS positionsNum, invaim.INV_AIM as invAim, invaim.BUSINESS_MODEL as businessModel, TEMP.ptlPositionsNum AS ptlPositionsNum,
FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctNo, SCI.ACCT_NAME acctName, /** 资金账户名称 **/ SDL.ITEM_VALUE AS tradeMarketStr FROM ( SELECT A.CDATE AS CDATE, A.PORTFOLIO_ID AS PORTFOLIO_ID , A.SEC_ACCT_ID AS SEC_ACCT_ID , A.FINPROD_ID AS FINPROD_ID, SUM(A.AMOUNT) AMOUNT, SUM(A.ptlPositionsNum) ptlPositionsNum from( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, SUM(PSP.AMOUNT) AMOUNT, 0 as ptlPositionsNum FROM PTL_SEC_POSITION_RULE PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.DATE_TYPE =0 AND PSP.HODING_TYPE=#{A_001} AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID union SELECT ETRPSP.CDATE AS CDATE, ETRPSP.PORTFOLIO_ID AS PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID AS SEC_ACCT_ID , ETRPSP.FINPROD_ID, 0 AS AMOUNT, SUM(ETRPSP.AMOUNT) as ptlPositionsNum FROM ETR_SEC_POSITION_RULE ETRPSP INNER JOIN PTL_PORTFOLIO PP ON ETRPSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE ETRPSP.DATE_TYPE =0 AND ETRPSP.CDATE = #{sysDate} GROUP BY ETRPSP.CDATE, ETRPSP.PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID, ETRPSP.FINPROD_ID) A GROUP BY A.CDATE, A.PORTFOLIO_ID , A.SEC_ACCT_ID, A.FINPROD_ID )TEMP LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO SCI ON SSAI.TRD_ACCT_ID = SCI.ACCT_NO
left join ( select FINPROD_ID, PORTFOLIO_ID, listagg(INV_AIM, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as INV_AIM, listagg(BUSINESS_MODEL, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as BUSINESS_MODEL from ( SELECT FINPROD_ID, PORTFOLIO_ID, INV_AIM,BUSINESS_MODEL FROM ( select a.INV_AIM ,a.BUSINESS_MODEL, a.TRADE_DATE ,a.FINPROD_ID,b.PORTFOLIO_ID, ROW_NUMBER () over( PARTITION BY a.TRADE_ID ORDER BY a.TRADE_DATE DESC ) rn from TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE <= #{sysDate} ) WHERE rn = 1 UNION SELECT a.FINPROD_ID, b.PORTFOLIO_ID, a.INV_AIM,'' as BUSINESS_MODEL from TRD_PRODUCT_TEMP_DEAL a LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE = #{sysDate} ) GROUP BY FINPROD_ID, PORTFOLIO_ID ) invaim on invaim.FINPROD_ID=TEMP.FINPROD_ID and invaim.PORTFOLIO_ID=TEMP.PORTFOLIO_ID LEFT JOIN SYS_DATADICT_LIST SDL ON SDL.DICT_CODE = 'TRADE_PLACE' AND FP.TRADE_MARKET = SDL.ITEM_CODE lEFT JOIN FIN_PRODUCT_TYPE FPT on FP.FINPROD_ID = FPT.FINPROD_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04}) AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND FPT.TYPE_10 = #{assetType,jdbcType=VARCHAR}
AND TEMP.PORTFOLIO_ID = #{portfolioName,jdbcType=VARCHAR}
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND TEMP.FINPROD_ID = #{finprodName,jdbcType=VARCHAR}
#{portfolioId,jdbcType=VARCHAR}
AND FP.FINPROD_ID in
#{item, jdbcType=VARCHAR}
) TEMP WHERE 1=1

SELECT * FROM( select trd_product_deal_add.portfolio_id portfolioId, /** 组合代码 **/ PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, /** 组合名称 **/ FIN_PRODUCT_TYPE.Type_7 as ps, /** 交易方向 **/ case when trd_fin_product_deal_total.totle_trade_id is not null then '已购回' else '未购回' end as purStatus, /** 购回状态 **/ case when fin_trade_product.Mdate <= #{sysdate,jdbcType=DATE} then #{YES_OR_NO_Y} else #{YES_OR_NO_N} end as isExpire, CASE WHEN fin_trade_product.Mdate <= #{sysdate,jdbcType=DATE} THEN '是' ELSE '否' END AS isExpireStr, /** 是否到期 **/ case when trd_product_deal_2.trade_id is not null then '已交收' else '未交收' end as settleStatus, /** 交收状态 **/ fin_trade_product.TERM repDays, /** 回购天数 **/ fin_trade_product.Mdate backDate, /** 回购到期日 **/ fin_trade_product.Trade_Market market, /** 市场 **/ /*fin_deal_pledge.pledge_finprod_id stockCode,*/ /** 质押券代码 **/ nvl(fp.FINPROD_NAME,fp.FINPROD_ABBR) stockName, nvl(fp.FINPROD_MARKET_ID,fin_deal_pledge.pledge_finprod_id) stockCode, fin_deal_pledge.Pledge_Ratio * 100 discountRate, /** 折算率 **/ fin_deal_pledge.Pledge_Number repSecNum, /** 质押券数量 **/ fin_deal_pledge.Pledge_Face_Value pledgeFaceValue,/** 质押券面值**/ fin_deal_pledge.Pledge_Face_Value * fin_deal_pledge.Pledge_Number pledStrdPrinAmt, /** 质押券面总额 **/ fin_trade_product.Prin tradeAmt, /** 回购金额 **/ fin_trade_product.INT_RATE * 100 yield, /** 回购利率 **/ fin_trade_product.vpay_date fristSettleDate, /** 首次结算日 **/ fin_trade_product.mpay_date expireSettleDate, /** 到期结算日 **/ case when fin_trade_product.mpay_date <= #{sysdate,jdbcType=DATE} then 0 else TO_NUMBER(fin_trade_product.mpay_date - #{sysdate,jdbcType=DATE}) end as remainDays, /** 剩余日期 **/ fin_trade_product.act_cap_days occupyDays, /** 实际占款天数 **/ fin_trade_product.m_int_amt mIntAmt, /** 回购利息 **/ fin_trade_product.m_Trade_Amt expireSettleAmt, /** 到期结算金额 **/
/*trd_product_deal_2.f_trade_id tradeId, trd_product_deal_2.f_trade_id intiTradeId,*/ std.cjbh tradeId, std.cjbh intiTradeId, SCI.ACCT_NAME AS acctName, fin_trade_product.term as term, mcp.counter_name counterName, /**交易对手名称**/ case when trd_product_deal_2.FINPROD_TYPE2 = 'F02' then eea.TRADER else ee.COUNTER_TRADER end as repurTraderId, /**正回购方交易员代码**/ case when trd_product_deal_2.FINPROD_TYPE2 = 'F02' then '' else eea.COUNTER_ORG end as repurOrgId, /**正回购方交易商代码**/ case when trd_product_deal_2.FINPROD_TYPE2 = 'F03' then eea.TRADER else ee.COUNTER_TRADER end as revRepurTraderId, /**逆回购方交易员代码**/ case when trd_product_deal_2.FINPROD_TYPE2 = 'F03' then '' else eea.COUNTER_ORG end as revRepurOrgId, /**逆回购方交易商代码**/ trd_product_deal_2.TRADER trader, trd_product_deal_add.DEALER_NO tradeName, trd_product_deal_add.DEALER_PARTY_NO AS investorName, trd_product_deal_2.COUNTER_TRADER counterTradeName, trd_product_deal_add.OUT_DEALER_NO counterDealerName, trd_product_deal_add.OUT_DEALER_PARTY_NO as counterInvestorName from fin_trade_product /** 交易类金融产品 **/ inner join FIN_PRODUCT_TYPE /** 金融产品分类表 **/ on fin_trade_product.finprod_id = FIN_PRODUCT_TYPE.Finprod_Id and fin_trade_product.BRANCH = FIN_PRODUCT_TYPE.Branch and FIN_PRODUCT_TYPE.Type_6 = 'H01' AND FIN_PRODUCT_TYPE.TYPE_7 in ('03', '04') INNER JOIN trd_product_deal trd_product_deal_2 /** 金融产品临时交易 **/ on fin_trade_product.finprod_id = trd_product_deal_2.Finprod_Id and fin_trade_product.branch = trd_product_deal_2.branch and trd_product_deal_2.ps in ('T01') LEFT JOIN trd_product_deal_add /** 金融产品临时交易附属表 **/ on trd_product_deal_2.trade_id = trd_product_deal_add.trade_id left join fin_deal_pledge /** 回购质押品 **/ on fin_trade_product.finprod_id = fin_deal_pledge.finprod_id AND fin_trade_product.branch = fin_deal_pledge.branch left join FIN_PRODUCT fp on fp.finprod_id = fin_deal_pledge.pledge_finprod_id LEFT JOIN settle_trans_data std on trd_product_deal_2.f_trade_id = std.trade_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ on trd_proEntrustMsgbyMQServiceduct_deal_add.Portfolio_Id = PTL_PORTFOLIO.Portfolio_Id LEFT JOIN trd_fin_product_deal_total trd_fin_product_deal_total /** 金融产品临时交易1 **/ on fin_trade_product.finprod_id = trd_fin_product_deal_total.finprod_id AND fin_trade_product.branch = trd_fin_product_deal_total.branch AND trd_fin_product_deal_total.ps in ('T96', 'T95', 'T93', 'T56', 'T07', 'T54') AND trd_fin_product_deal_total.trade_status = '01' AND trd_fin_product_deal_total.is_cancel = 'N' LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id LEFT JOIN STL_SEC_ACCT_INFO SSAI ON trd_product_deal_2.SEC_MANAGE_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO SCI ON SSAI.TRD_ACCT_ID = SCI.ACCT_NO LEFT JOIN ETR_ENTRUST ee ON trd_product_deal_add.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD eea ON ee.ENTRUST_ID = eea.ENTRUST_ID LEFT JOIN mst_counter_party mcp ON ee.counter_id = mcp.counter_id where fin_trade_product.branch = 0 AND fin_trade_product.trade_market IN ('03', '04') AND trd_product_deal_2.trade_status = '01' and trd_product_deal_2.is_cancel = 'N'
AND (fin_trade_product.finprod_id = #{tradeId,jdbcType=VARCHAR} or trd_product_deal_2.F_TRADE_ID = #{tradeId,jdbcType=VARCHAR})
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND trd_product_deal_add.portfolio_id = #{portfolioId}
#{item}
AND fin_trade_product.Trade_Market = #{tradeMarket}
AND trd_product_deal_2.sec_manage_acct_id = #{secAcctId}
AND FIN_PRODUCT_TYPE.TYPE_7 = #{repPs}
AND fin_deal_pledge.pledge_finprod_id = #{pledgeFinprodId}
#{item}
)PRODUCT LEFT JOIN SYS_DATADICT_LIST SDL1 ON SDL1.DICT_CODE ='PS' AND SDL1.ITEM_CODE = PRODUCT.ps LEFT JOIN SYS_DATADICT_LIST SDL2 ON SDL2.DICT_CODE ='TRADE_MARKET' AND SDL2.ITEM_CODE = PRODUCT.market WHERE 1=1
order by ${pageMode.sort} ${pageMode.direction}

select distinct * from ( select etr_entrust.entrust_id entrustId, /** 指令编号 **/ etr_entrust.entrust_status entrustStatus, /** 指令状态 **/
CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ) / nvl( etr_entrust.ENTRUST_NUM, 1 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ) / nvl( etr_entrust.ENTRUST_AMT, 1 ), 4 ) END AS implementPercent, CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ) / nvl( etr_entrust.ENTRUST_NUM, 1 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ) / nvl( etr_entrust.ENTRUST_AMT, 1 ), 4 ) END AS dealPercent, CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, SCI.ACCT_NAME dealCurAcct, /** 资金账户 **/
etr_entrust.trade_market tradeMarket, /** 市场 **/ etr_entrust.Trade_Plat tradePlat, /** 交易平台 **/ etr_entrust.Ps ps, /** 交易方向 **/ etr_entrust_add.BUSI_PS busiPs,/**委托方向**/ etr_entrust_add.Term_Days term,/** 回购期限 **/ etr_entrust.entrust_amt entrustAmt, /** 回购金额 **/ etr_entrust.Price * 100 price, /** 回购利率 **/ etr_entrust_add.vpay_date fristSettleDate,/** 首期结算日 **/ etr_entrust_add.mpay_date expireSettleDate,/** 到期结算日 **/ etr_entrust_add.Cap_Days occupyDays,/** 占款天数 **/ etr_entrust_add.m_Int_Amt intAmt,/** 回购利息 **/ etr_entrust_add.m_Trade_Amt expireSettleAmt,/** 到期结算金额 **/ etr_pledge.finprod_id finprodId, /** 金融产品代码 **/ fin_product.Finprod_Market_Id finprodMarketId, /** 质押代码 **/ fin_product.finprod_abbr finprodAbbr, /** 质押券名称 **/ etr_pledge.Pledge_Ratio * 100 conRatio, /** 折算率 **/ etr_pledge.PLEDGE_NUMBER/100 repSecNum, /** 质押数量 **/ case when etr_entrust.trade_market = #{TRADE_PLACE_03} then #{UNIT_04} else #{UNIT_01} end as pledgeUnit, /** 质押券单位 **/ etr_pledge.PLEDGE_NUMBER * nvl(etr_pledge.Pledge_Face_Value, 100) printAmt, /** 质押面额 **/ etr_entrust_add.Sec_Acct_Id secAcctId, /** 证券账户 ※隐藏 **/ etr_entrust.counter_id counterId, /** 交易对手 **/ mst_counter_party.counter_name counterName, /**交易对手名称**/ etr_entrust.counter_trader counterTrader,/** 对手方交易员 **/ etr_entrust.vdate vdate,/** 开始日期 **/ etr_entrust.mdate mdate,/** 结束日期 **/ etr_entrust.CREATE_TIME, '' nextUser, etr_entrust.INV_MANAGER_ID invManagerId, etr_entrust.ENTRUST_DATE entrustDate, SDL1.ITEM_VALUE entrustStatusString, SDL2.ITEM_VALUE tradeMarketString, SDL3.ITEM_VALUE tradePlatString, SDL4.ITEM_VALUE psStr, SDL5.ITEM_VALUE busiTypeTgString, btm.OUTPUT_VALUE_1 busiTypeTg, SYS_USER.REAL_NAME invManagerName, etr_entrust_add.TRADER as homeTrader, etr_entrust.REMARK as addCla, etr_entrust_add.REQUEST_ID as requestId, etr_entrust_add.TRADE_ID as intiTradeId from etr_entrust /** 委托指令 **/ inner JOIN etr_entrust_add /** 委托指令附属 **/ ON etr_entrust.entrust_id = etr_entrust_add.entrust_id LEFT JOIN etr_pledge /** 委托指令回购质押品 **/ ON etr_entrust.entrust_id = etr_pledge.entrust_id LEFT JOIN etr_finish_status /** 委托完成状况表 **/ ON etr_entrust.entrust_id = etr_finish_status.entrust_id and etr_entrust.entrust_id = etr_finish_status.trade_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ ON etr_entrust.portfolio_id = PTL_PORTFOLIO.Portfolio_Id
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON etr_entrust.ENTRUST_ID = detail.ENTRUST_ID
LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id LEFT JOIN fin_product /** 标的类金融产品 **/ ON fin_product.finprod_id = etr_entrust.finprod_id LEFT JOIN mst_counter_party /** 交易对手 **/ ON etr_entrust.counter_id = mst_counter_party.counter_id LEFT JOIN STL_CAPACCT_INFO SCI ON etr_entrust_add.Deal_Cur_Acct = SCI.ACCT_NO LEFT JOIN SYS_DATADICT_LIST SDL1 ON SDL1.DICT_CODE ='ENTRUST_STATUS' AND SDL1.ITEM_CODE = etr_entrust.entrust_status LEFT JOIN SYS_DATADICT_LIST SDL2 ON SDL2.DICT_CODE ='TRADE_PLACE' AND SDL2.ITEM_CODE = etr_entrust.trade_market LEFT JOIN SYS_DATADICT_LIST SDL3 ON SDL3.DICT_CODE ='SHARES_TRADE_PLATFORM' AND SDL3.ITEM_CODE = etr_entrust.Trade_Plat LEFT JOIN SYS_DATADICT_LIST SDL4 ON SDL4.DICT_CODE ='PS' AND SDL4.ITEM_CODE = etr_entrust_add.BUSI_PS LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN SYS_USER ON ETR_ENTRUST.INV_MANAGER_ID = SYS_USER.USER_NAME LEFT JOIN SYS_DATADICT_LIST SDL5 ON SDL5.DICT_CODE ='BUSI_TYPE_TG' AND SDL5.ITEM_CODE = btm.OUTPUT_VALUE_1 where etr_entrust.TRADE_MARKET IN ('03','04') and etr_entrust_add.ASSET_TYPE1 = 'H01'
AND etr_entrust.ENTRUST_STATUS = #{entrustStatus}
AND etr_entrust.ENTRUST_ID = #{entrustId}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND PTL_PORTFOLIO.Portfolio_Id = #{portfolioName}
#{item}
AND etr_entrust.trade_market = #{tradeMarket}
AND etr_pledge.finprod_id = #{finprodId}
#{item}
AND etr_entrust.Ps in ('03', '04')
AND etr_entrust.Ps = #{bussType}
AND etr_entrust.INV_MANAGER_ID = #{manager}
AND etr_entrust.ENTRUST_DATE >= to_date(#{startDate},'yyyy-mm-dd') AND etr_entrust.ENTRUST_DATE <= to_date(#{endDate},'yyyy-mm-dd')
union all select wfl_etr_entrust.entrust_id entrustId, /** 指令编号 **/ '08' entrustStatus, /** 指令状态 **/ CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ) / nvl( wfl_etr_entrust.ENTRUST_NUM, 1 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ) / nvl( wfl_etr_entrust.ENTRUST_AMT, 1 ), 4 ) END AS implementPercent, CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ) / nvl( wfl_etr_entrust.ENTRUST_NUM, 1 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ) / nvl( wfl_etr_entrust.ENTRUST_AMT, 1 ), 4 ) END AS dealPercent, CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( wfl_etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( wfl_etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN wfl_etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( wfl_etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( wfl_etr_entrust.ENTRUST_NUM, 0 ) - nvl( etr_finish_status.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, SCI.ACCT_NAME dealCurAcct, /** 资金账户 **/
wfl_etr_entrust.trade_market tradeMarket, /** 市场 **/ wfl_etr_entrust.Trade_Plat tradePlat, /** 交易平台 **/ wfl_etr_entrust.Ps ps, /** 交易方向 **/ wfl_etr_entrust_add.BUSI_PS busiPs,/**委托方向**/ wfl_etr_entrust_add.Term_Days term,/** 回购期限 **/ wfl_etr_entrust.entrust_amt entrustAmt, /** 回购金额 **/ wfl_etr_entrust.Price * 100 price, /** 回购利率 **/ wfl_etr_entrust_add.vpay_date fristSettleDate,/** 首期结算日 **/ wfl_etr_entrust_add.mpay_date expireSettleDate,/** 到期结算日 **/ wfl_etr_entrust_add.Cap_Days occupyDays,/** 占款天数 **/ wfl_etr_entrust_add.m_Int_Amt intAmt,/** 回购利息 **/ wfl_etr_entrust_add.m_Trade_Amt expireSettleAmt,/** 到期结算金额 **/ wfl_etr_pledge.finprod_id finprodId, /** 金融产品代码 **/ fin_product.Finprod_Market_Id finprodMarketId, /** 质押代码 **/ fin_product.finprod_abbr finprodAbbr, /** 质押券名称 **/ wfl_etr_pledge.Pledge_Ratio * 100 conRatio, /** 折算率 **/ wfl_etr_pledge.PLEDGE_NUMBER repSecNum, /** 质押数量 **/ case when wfl_etr_entrust.trade_market = #{TRADE_PLACE_03} then #{UNIT_04} else #{UNIT_01} end as pledgeUnit, /** 质押券单位 **/ wfl_etr_pledge.PLEDGE_NUMBER * nvl(wfl_etr_pledge.Pledge_Face_Value, 100) printAmt, /** 质押面额 **/ wfl_etr_entrust_add.Sec_Acct_Id secAcctId, /** 证券账户 ※隐藏 **/ wfl_etr_entrust.counter_id counterId, /** 交易对手 **/ mst_counter_party.counter_name counterName, /**交易对手名称**/ wfl_etr_entrust.counter_trader counterTrader,/** 对手方交易员 **/ wfl_etr_entrust.vdate vdate,/** 开始日期 **/ wfl_etr_entrust.mdate mdate/** 结束日期 **/ ,wfl_etr_entrust.CREATE_TIME ,SWBL.NEXT_USER nextUser, wfl_etr_entrust.INV_MANAGER_ID invManagerId, wfl_etr_entrust.ENTRUST_DATE entrustDate, '流程中' entrustStatusString, SDL2.ITEM_VALUE tradeMarketString, SDL3.ITEM_VALUE tradePlatString, SDL4.ITEM_VALUE psStr, SDL5.ITEM_VALUE busiTypeTgString, btm.OUTPUT_VALUE_1 busiTypeTg, SYS_USER.REAL_NAME invManagerName, wfl_etr_entrust_add.TRADER as homeTrader, wfl_etr_entrust.REMARK as addCla, wfl_etr_entrust_add.REQUEST_ID as requestId, wfl_etr_entrust_add.TRADE_ID as intiTradeId from wfl_etr_entrust inner JOIN wfl_etr_entrust_add ON wfl_etr_entrust.entrust_id = wfl_etr_entrust_add.entrust_id LEFT JOIN wfl_etr_pledge /** 委托指令回购质押品 **/ ON wfl_etr_entrust.entrust_id = wfl_etr_pledge.entrust_id LEFT JOIN etr_finish_status /** 委托完成状况表 **/ ON wfl_etr_entrust.entrust_id = etr_finish_status.entrust_id and wfl_etr_entrust.entrust_id = etr_finish_status.trade_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ ON wfl_etr_entrust.portfolio_id = PTL_PORTFOLIO.Portfolio_Id
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON wfl_etr_entrust.ENTRUST_ID = detail.ENTRUST_ID
LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id LEFT JOIN fin_product /** 标的类金融产品 **/ ON fin_product.finprod_id = wfl_etr_entrust.finprod_id LEFT JOIN mst_counter_party /** 交易对手 **/ ON wfl_etr_entrust.counter_id = mst_counter_party.counter_id LEFT JOIN STL_CAPACCT_INFO SCI ON wfl_etr_entrust_add.Deal_Cur_Acct = SCI.ACCT_NO LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = wfl_etr_entrust.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END' LEFT JOIN SYS_DATADICT_LIST SDL2 ON SDL2.DICT_CODE ='TRADE_PLACE' AND SDL2.ITEM_CODE = wfl_etr_entrust.trade_market LEFT JOIN SYS_DATADICT_LIST SDL3 ON SDL3.DICT_CODE ='SHARES_TRADE_PLATFORM' AND SDL3.ITEM_CODE = wfl_etr_entrust.Trade_Plat LEFT JOIN SYS_DATADICT_LIST SDL4 ON SDL4.DICT_CODE ='PS' AND SDL4.ITEM_CODE = wfl_etr_entrust_add.BUSI_PS LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (wfl_etr_entrust.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (wfl_etr_entrust.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (wfl_etr_entrust.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN SYS_USER ON wfl_etr_entrust.INV_MANAGER_ID = SYS_USER.USER_NAME LEFT JOIN SYS_DATADICT_LIST SDL5 ON SDL5.DICT_CODE ='BUSI_TYPE_TG' AND SDL5.ITEM_CODE = btm.OUTPUT_VALUE_1 where wfl_etr_entrust.TRADE_MARKET IN ('03','04') and wfl_etr_entrust_add.ASSET_TYPE1 = 'H01'
AND wfl_etr_entrust.ENTRUST_STATUS = #{entrustStatus}
AND wfl_etr_entrust.ENTRUST_ID = #{entrustId}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND PTL_PORTFOLIO.Portfolio_Id = #{portfolioName}
#{item}
AND wfl_etr_entrust.trade_market = #{tradeMarket}
AND wfl_etr_pledge.finprod_id = #{finprodId}
#{item}
AND wfl_etr_entrust.Ps in ('03', '04')
AND wfl_etr_entrust.Ps = #{bussType}
AND wfl_etr_entrust.INV_MANAGER_ID = #{manager}
AND wfl_etr_entrust.ENTRUST_DATE >= to_date(#{startDate},'yyyy-mm-dd') AND wfl_etr_entrust.ENTRUST_DATE <= to_date(#{endDate},'yyyy-mm-dd')
) T1 WHERE 1=1
order by ${pageMode.sort} ${pageMode.direction}
ORDER BY T1.CREATE_TIME DESC

select
max(t.cdate)
from etr_sec_position t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.sec_acct_id = #{secAcctId}


    and t.finprod_id = #{finprodId,jdbcType=VARCHAR}


    and t.branch = #{branch,jdbcType=DECIMAL}


    and t.INV_AIM = #{invAim}



    and t.INV_AIM != '999999'

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate <= #{cdate,jdbcType=DATE}

select
sum(t.amount) as amount
from etr_sec_position t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.sec_acct_id = #{secAcctId}


    and t.finprod_id = #{finprodId,jdbcType=VARCHAR}


    and t.branch = #{branch,jdbcType=DECIMAL}


    and t.INV_AIM = #{invAim}



    and t.INV_AIM != '999999'

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate = #{cdate,jdbcType=DATE}

SELECT F.FINPROD_ID id, F.FINPROD_ABBR TEXT FROM FIN_PRODUCT F
F.TRADE_MARKET IN (#{TRADE_PLACE_03,jdbcType=VARCHAR},#{TRADE_PLACE_04,jdbcType=VARCHAR}) AND F.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR} AND F.MDATE >= #{sysDate,jdbcType=DATE}
AND (F.FINPROD_ID like concat('%',concat(#{search},'%')) OR F.FINPROD_ABBR concat('%',concat(#{search},'%')))

select T.TRADE_ID ID, T.TRADE_ID TEXT
from trd_product_deal T
WHERE

    T.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03})
    AND T.TRADE_MARKET IN (#{TRADE_PLACE_03,jdbcType=VARCHAR},#{TRADE_PLACE_04,jdbcType=VARCHAR})
    AND T.PS = #{ps_T01}
    AND T.IS_CANCEL = #{YES_OR_NO_N}
    AND T.TRADE_STATUS = #{TRADE_STATUS_01}

       AND  T.TRADE_ID  like concat('%',concat(#{search},'%'))

select count(1) from ( SELECT ee.ENTRUST_ID FROM ETR_ENTRUST ee INNER JOIN ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID WHERE ee.PS = #{ps,jdbcType=VARCHAR} and eea.TRADE_ID = #{initTradeId,jdbcType=VARCHAR} and ee.ENTRUST_STATUS != '06'
UNION SELECT ee.ENTRUST_ID FROM ETR_ENTRUST_BACKUP ee INNER JOIN ETR_ENTRUST_ADD_BACKUP eea on ee.ENTRUST_ID = eea.ENTRUST_ID WHERE ee.PS = #{ps,jdbcType=VARCHAR} and eea.TRADE_ID = #{initTradeId,jdbcType=VARCHAR}
UNION SELECT ee.ENTRUST_ID FROM WFL_ETR_ENTRUST ee INNER JOIN WFL_ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID WHERE ee.PS = #{ps,jdbcType=VARCHAR} and eea.TRADE_ID = #{initTradeId,jdbcType=VARCHAR} )
